import json
import math
from pathlib import Path
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, str(Path(sys.argv[1]).resolve()))
import pydash as pyd


def require(condition, message):
    if not condition:
        raise AssertionError(message)


def generator(values):
    yield from values


FACTORIES = [('list', list), ('tuple', tuple), ('iterator', iter), ('generator', generator)]


def collection_shapes():
    rows = []
    for name, factory in FACTORIES:
        for values, expected in [([7], 7), ([5, 1, 3], 3), ([4, 1, 3, 2], 2.5)]:
            result = pyd.median(factory(values))
            require(result == expected, 'wrong median for ' + name)
            rows.append({'factory': name, 'values': values, 'median': result})
    return rows


def callable_iteratees():
    rows = []
    for name, factory in FACTORIES:
        require(pyd.median(factory([5, 1, 3]), lambda value: -value) == -3, 'unary iteratee')
        require(pyd.median(factory([4, 1, 3, 2]), lambda value: value ** 2) == 6.5, 'even mapped median')
        source = factory([5, 1, 3])
        calls = []
        def inspect_source(value, key, collection):
            require(collection is source, 'callback original-collection identity changed')
            calls.append([key, value])
            return value + key
        result = pyd.median(source, inspect_source)
        require(result == 5 and calls == [[0, 5], [1, 1], [2, 3]], 'callback index/order changed')
        rows.append({'factory': name, 'mapped_median': result, 'calls': calls, 'original_source_identity': True})
    return rows


def shorthand_and_mapping():
    rows = []
    records = [{'score': 9}, {'score': 1}, {'score': 5}, {'score': 3}]
    for name, factory in FACTORIES:
        result = pyd.median(factory(records), 'score')
        require(result == 4, 'property shorthand median')
        rows.append({'factory': name, 'median': result})
    mapping = {'one': {'score': 3}, 'two': {'score': 1}, 'three': {'score': 2}}
    require(pyd.median(mapping, 'score') == 2, 'mapping values/property path changed')
    numbers = {'a': 1, 'bb': 2, 'ccc': 3}
    require(pyd.median(numbers, lambda value, key: value + len(key)) == 4, 'mapping key callback changed')
    return {'records': rows, 'mapping_property_median': 2, 'mapping_key_median': 4}


def empty_inputs():
    rows = []
    for name, factory in FACTORIES + [('dict', dict)]:
        calls = []
        def unexpected(value):
            calls.append(value)
            raise RuntimeError('empty input must not call iteratee')
        for iteratee_name, iteratee in [('none', None), ('callback', unexpected), ('builtin_int', int)]:
            result = pyd.median(factory([]), iteratee)
            require(math.isnan(result), 'empty input changed from NaN')
            rows.append({'factory': name, 'iteratee': iteratee_name, 'is_nan': True})
        require(calls == [], 'empty input evaluated iteratee')
    return rows


def single_pass_iterable():
    class Stream:
        def __init__(self):
            self.values = iter([5, 1, 3])
            self.visited = []
        def __iter__(self):
            return self
        def __next__(self):
            value = next(self.values)
            self.visited.append(value)
            return value
    source = Stream()
    require(pyd.median(source) == 3, 'non-Sized iterator median')
    require(source.visited == [5, 1, 3], 'iterator values consumed more than once')
    return {'visited': source.visited, 'median': 3}


def does_not_mutate_input():
    values = [5, 1, 3]
    require(pyd.median(values) == 3 and values == [5, 1, 3], 'source list reordered')
    records = [{'n': 5}, {'n': 1}, {'n': 3}]
    require(pyd.median(records, 'n') == 3, 'record median')
    require(records == [{'n': 5}, {'n': 1}, {'n': 3}], 'record collection mutated')
    return {'values': values, 'records': records}


def iterator_failures():
    rows = []
    for kind in [ValueError, RuntimeError]:
        failure = kind('iteration failure')
        def broken():
            yield 1
            raise failure
        caught = None
        try:
            pyd.median(broken())
        except BaseException as error:
            caught = error
        require(caught is failure, 'iterator failure replaced or treated as empty')
        rows.append({'exception': kind.__name__, 'original_identity': True})
    return rows


def iteratee_failures():
    rows = []
    for name, factory in FACTORIES:
        failure = ValueError('transform failure')
        def transform(value):
            raise failure
        caught = None
        try:
            pyd.median(factory([1, 2, 3]), transform)
        except BaseException as error:
            caught = error
        require(caught is failure, 'iteratee failure replaced or treated as empty')
        rows.append({'factory': name, 'original_identity': True})
    return rows


results = {}
for function in [collection_shapes, callable_iteratees, shorthand_and_mapping, empty_inputs,
                 single_pass_iterable, does_not_mutate_input, iterator_failures, iteratee_failures]:
    try:
        results[function.__name__] = {'passed': True, 'observed': function()}
    except BaseException as error:
        results[function.__name__] = {'passed': False, 'exception': type(error).__name__, 'message': str(error)}

class AttributeObject:
    def __init__(self):
        self.a, self.b, self.c = 1, 3, 2

outside = []
for label, value in [('None', None), ('integer', 3), ('plain_object', object()), ('attribute_object', AttributeObject())]:
    try:
        result = pyd.median(value)
        outside.append({'kind': label, 'exception': None, 'outcome': 'NaN' if math.isnan(result) else result})
    except BaseException as error:
        outside.append({'kind': label, 'exception': type(error).__name__, 'outcome': None})

print(json.dumps({'module_file': str(Path(pyd.__file__).resolve()),
                  'passed': sum(result['passed'] for result in results.values()), 'total': len(results),
                  'results': results, 'outside_declared_iterable_contract_observations': outside}))
